package com.proofclean.analysis.service;
import com.proofclean.analysis.entity.*;import org.springframework.stereotype.Service;import java.util.List;
@Service
public class RiskScoringService { public int calculate(AnalysisPurpose purpose, List<DetectionFinding> findings){ int score=0; boolean critical=false; for(var f:findings){ score += switch(f.getSeverity()){ case LOW -> 10; case MEDIUM -> 20; case HIGH -> 35; case CRITICAL -> 50; }; if(f.getSeverity()==Severity.CRITICAL) critical=true; if(purpose==AnalysisPurpose.SECOND_HAND && List.of(DetectionType.ADDRESS,DetectionType.PHONE,DetectionType.INVOICE).contains(f.getDetectionType())) score+=15; if(purpose==AnalysisPurpose.SNS && List.of(DetectionType.LOCATION_HINT,DetectionType.FACE,DetectionType.EXIF).contains(f.getDetectionType())) score+=10; if(purpose==AnalysisPurpose.ASSIGNMENT && List.of(DetectionType.STUDENT_ID,DetectionType.EMAIL,DetectionType.SCREEN_TEXT).contains(f.getDetectionType())) score+=10; } if(findings.size()>=5) score+=10; if(critical) score=Math.max(score,80); return Math.max(0, Math.min(100, score)); } }
